import base64, sys, json
sys.path.insert(0, "src")
sys.path.insert(0, "review/llm-guided-heuristic-route-2026-09-15/tools")
src = base64.b64decode("").decode("utf-8")
print("src_bytes", len(src.encode("utf-8")))
from hangma_bot.policy.action_value_executor import static_check, ActionValueExecutor
static_check(src)
print("static_check OK")
import sitin_gates as gates
ex = ActionValueExecutor(src, name="<test>")
for name in ("sample", "route_combo", "unknown_missing", "max_input", "fam_hu", "fam_pass", "fam_chi", "fam_peng", "fam_gang", "fam_discard"):
    view = gates.AV_VIEW_FIXTURES[name]()
    batch = ex.score(view)
    print(name, batch.status, len(batch.entries), "ops=", ex.last_operation_count,
          [(e.action_key, round(e.score, 2)) for e in batch.entries])
    if name == "sample":
        print("  trace0", json.dumps(batch.entries[0].trace, ensure_ascii=False))
